// Generated from src/registry/sources/control-ui/recipes/button-group.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const buttonGroupKnobs = [
  "--cui-button-group-text-radius",
  "--cui-button-group-text-background",
  "--cui-button-group-text-foreground",
  "--cui-button-group-separator-background",
] as const;
export type ButtonGroupKnobStyle = Partial<Record<(typeof buttonGroupKnobs)[number], string>>;

@layer components {
  :where([data-control-family="button-group"][data-slot="root"]) {
    --cui-button-group-text-radius: var(--radius-control);
    --cui-button-group-text-background: var(--control-fill);
    --cui-button-group-text-foreground: var(--muted-foreground);
    --cui-button-group-separator-background: var(--border);
  }

  :where([data-control-family="button-group"][data-slot="text"]) {
    block-size: var(--control-h-md);
    border: 1px solid var(--border);
    border-radius: var(--cui-button-group-text-radius);
    background: var(--cui-button-group-text-background);
    box-shadow: var(--shadow-sm);
    padding-inline: var(--padding-x);
    color: var(--cui-button-group-text-foreground);
    font-size: var(--text-body);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="button-group"][data-slot="text"][data-size="xs"]) {
    block-size: var(--control-h-xs);
    padding-inline: calc(var(--padding-x) * 0.6);
    font-size: var(--text-caption);
  }

  :where([data-control-family="button-group"][data-slot="text"][data-size="sm"]) {
    block-size: var(--control-h-sm);
    padding-inline: calc(var(--padding-x) * 0.75);
    font-size: var(--text-label);
  }

  :where([data-control-family="button-group"][data-slot="text"][data-size="lg"]) {
    block-size: var(--control-h-lg);
    padding-inline: calc(var(--padding-x) * 1.25);
  }

  :where([data-control-family="button-group"][data-slot="separator"]) {
    background: var(--cui-button-group-separator-background);
  }
  :where([data-control-family="button-group"][data-slot="root"] > :not([data-control-family="track-highlight"])) {
    position: relative;
  }

  :where(
    [data-control-family="button-group"][data-orientation="horizontal"]
      > :not([data-control-family="track-highlight"])
      + :not([data-control-family="track-highlight"])
  ) {
    margin-inline-start: -1px;
    border-start-start-radius: 0;
    border-end-start-radius: 0;
  }

  :where([data-control-family="button-group"][data-orientation="horizontal"] > :has(~ :not([data-control-family="track-highlight"]))) {
    border-start-end-radius: 0;
    border-end-end-radius: 0;
  }

  :where(
    [data-control-family="button-group"][data-orientation="vertical"]
      > :not([data-control-family="track-highlight"])
      + :not([data-control-family="track-highlight"])
  ) {
    margin-block-start: -1px;
    border-start-start-radius: 0;
    border-start-end-radius: 0;
  }

  :where([data-control-family="button-group"][data-orientation="vertical"] > :has(~ :not([data-control-family="track-highlight"]))) {
    border-end-start-radius: 0;
    border-end-end-radius: 0;
  }

  :where([data-control-family="button-group"][data-slot="root"] > :focus-within) {
    z-index: 1;
  }

  :where([data-control-family="button-group"][data-slot="root"] > [data-active="true"]) {
    z-index: 2;
  }

  :where([data-control-family="button-group"][data-slot="root"] > [data-active="true"]:focus-within) {
    z-index: 3;
  }

  @media (pointer: coarse) {
    :where(
        [data-control-family="button-group"][data-slot="root"][data-orientation="vertical"] [data-control-family="button"][data-size="xs"]
      )::after {
      block-size: 100%;
    }
  }
}

@property --cui-button-group-text-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-button-group-text-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-button-group-text-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-button-group-separator-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import type { ComponentProps, CSSProperties } from "react";
import type { HoverIndicator } from "@/components/control-ui/control-props";
import type { ControlSize } from "@/components/control-ui/control-variants";
import { TrackHighlight } from "@/components/control-ui/extensions/track-highlight";
import type { ButtonGroupKnobStyle } from "@/components/control-ui/knob-contracts/button-group-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { useSkin } from "@/components/control-ui/skin-provider";

import { ButtonTrackContext, buttonTrackStructureClasses } from "@/components/control-ui/ui/button";

export type ButtonGroupTextProps = Omit<
  ComponentProps<"div"> & {
    size?: ControlSize;
  },
  "style"
> & { style?: CSSProperties & ButtonGroupKnobStyle };

export type ButtonGroupProps = ComponentProps<"div"> & {
  orientation?: "horizontal" | "vertical";
  indicator?: HoverIndicator;
} & { style?: CSSProperties & ButtonGroupKnobStyle };

export type ButtonGroupSeparatorProps = Omit<
  ComponentProps<"div"> & {
    orientation?: "horizontal" | "vertical";
  },
  "style"
> & { style?: CSSProperties & ButtonGroupKnobStyle };

export function ButtonGroup({ orientation = "horizontal", indicator, className, children, ...props }: ButtonGroupProps) {
  const skin = useSkin();
  const resolvedIndicator = indicator ?? skin.indicators?.["button-group"] ?? "none";
  const tracksHover = resolvedIndicator === "hover";
  return (
    <ButtonTrackContext value={tracksHover}>
      {/* biome-ignore lint/a11y/useSemanticElements: a segmented control is a labelled group, not a fieldset form group. */}
      <div
        role="group"
        data-control-ui="button-group"
        data-control-family="button-group"
        data-slot="root"
        data-orientation={orientation}
        data-track={resolvedIndicator}
        className={cn(buttonTrackStructureClasses, "inline-flex w-fit items-stretch data-[orientation=vertical]:flex-col", className)}
        {...props}
      >
        {children}
        {tracksHover ? <TrackHighlight className="z-0" /> : null}
      </div>
    </ButtonTrackContext>
  );
}

export function ButtonGroupText({ size = "sm", className, ...props }: ButtonGroupTextProps) {
  return (
    <div
      data-control-ui="button-group"
      data-control-family="button-group"
      data-slot="text"
      data-size={size}
      className={cn("inline-flex items-center whitespace-nowrap [&>svg]:pointer-events-none [&>svg]:size-4 [&>svg]:shrink-0", className)}
      {...props}
    />
  );
}

export function ButtonGroupSeparator({ orientation = "vertical", className, ...props }: ButtonGroupSeparatorProps) {
  return (
    <div
      aria-hidden="true"
      data-control-ui="button-group"
      data-control-family="button-group"
      data-slot="separator"
      data-orientation={orientation}
      className={cn("shrink-0 self-stretch", orientation === "vertical" ? "w-px" : "h-px w-full", className)}
      {...props}
    />
  );
}
